import{_ as o,o as r,c as a,a3 as s}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"第十章　神经网络时间序列模型","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/10.md","filePath":"timeseries/10.md"}'),n={name:"timeseries/10.md"};function l(e,t,i,d,p,g){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="第十章-神经网络时间序列模型" tabindex="-1">第十章　神经网络时间序列模型 <a class="header-anchor" href="#第十章-神经网络时间序列模型" aria-label="Permalink to &quot;第十章　神经网络时间序列模型&quot;">​</a></h1><p>神经网络是自回归模型的非线性推广。本章讲 NNAR 的结构与超参数、为什么它不做趋势外推，以及它在小样本经济序列上常输给 ARIMA 的原因。</p><h2 id="_10-1-nnar-的结构" tabindex="-1">10.1 NNAR 的结构 <a class="header-anchor" href="#_10-1-nnar-的结构" aria-label="Permalink to &quot;10.1 NNAR 的结构&quot;">​</a></h2><p><strong>NNAR(p, k)</strong> 指&quot;自回归神经网络&quot;：用 p 个滞后作为输入，k 个隐藏节点，输出 1 个预测值。</p><p>数学形式为</p><blockquote><p><strong>ŷₜ = β₀ + Σⱼ₌₁ᵏ βⱼ · σ( aⱼ₀ + Σᵢ₌₁ᵖ aⱼᵢ yₜ₋ᵢ )</strong></p></blockquote><p>其中 σ 是激活函数（通常是 sigmoid：σ(z) = 1/(1 + e⁻ᶻ)），a 是输入层到隐藏层的权重，β 是隐藏层到输出层的权重。</p><p><strong>结构层次</strong>：</p><ul><li>输入层：p 个节点，对应 yₜ₋₁, …, yₜ₋p；</li><li>隐藏层：k 个节点，每个节点对输入做加权求和再过激活函数；</li><li>输出层：1 个节点，对隐藏层输出做<strong>线性</strong>加权求和。</li></ul><p>若含季节项，则记为 NNAR(p, P, k)_m，输入增加季节滞后 yₜ₋m, yₜ₋₂m, …。</p><h2 id="_10-2-与-ar-模型的关系" tabindex="-1">10.2 与 AR 模型的关系 <a class="header-anchor" href="#_10-2-与-ar-模型的关系" aria-label="Permalink to &quot;10.2 与 AR 模型的关系&quot;">​</a></h2><p>★ <strong>NNAR 是 AR 模型的非线性推广</strong>，两者关系可以这样理解：</p><ul><li>若<strong>没有隐藏层</strong>（或隐藏层只有 1 个节点且激活函数为恒等），NNAR 退化为线性 AR(p)；</li><li>有隐藏层且激活函数非线性时，模型可以逼近任意连续函数（万能逼近定理）；</li><li>因此 NNAR 的能力上限高于 AR，但<strong>需要更多样本才能实现</strong>。</li></ul><p>这也解释了为什么 NNAR 在小样本上常常不如 ARIMA：它的参数更多、假设更弱，但数据量不足以支撑这种灵活性。</p><h2 id="_10-3-关键超参数" tabindex="-1">10.3 关键超参数 <a class="header-anchor" href="#_10-3-关键超参数" aria-label="Permalink to &quot;10.3 关键超参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>含义</th><th>典型设置</th><th>影响</th></tr></thead><tbody><tr><td>p</td><td>输入滞后个数（记忆长度）</td><td>由线性 AR 的 AIC 最优阶给出，或网格搜索</td><td>太小则记忆不足，太大则参数爆炸</td></tr><tr><td>k（size）</td><td>隐藏节点数</td><td>常见默认 ≈ (p + P + 1)/2</td><td>控制非线性容量；太大易过拟合</td></tr><tr><td>decay</td><td>权重衰减系数（L2 正则）</td><td>0 到 0.1</td><td>抑制过拟合，等价于对权重的惩罚</td></tr><tr><td>maxit</td><td>最大迭代次数</td><td>100 到 500</td><td>太小则未收敛，太大则耗时</td></tr><tr><td>repeats</td><td>重复训练次数</td><td>20</td><td>每次随机初始化，取平均以降方差</td></tr></tbody></table><p>★ <strong>k 的选择是偏差–方差权衡的典型体现。</strong> k 太小，模型接近线性，无法捕捉非线性；k 太大，参数过多，在有限样本上严重过拟合。经验做法是从 k ≈ (p+1)/2 开始，在验证集上比较几个候选。</p><p>★ <strong>decay 的作用</strong>。它给权重的平方和加上惩罚项，使权重倾向于取小值。效果是让网络输出更平滑、更接近线性，从而降低过拟合风险。代价是可能欠拟合。</p><h2 id="_10-4-为什么-nnar-不做趋势外推" tabindex="-1">10.4 为什么 NNAR 不做趋势外推 <a class="header-anchor" href="#_10-4-为什么-nnar-不做趋势外推" aria-label="Permalink to &quot;10.4 为什么 NNAR 不做趋势外推&quot;">​</a></h2><p>这是一个结构性特征，不是训练不足。</p><p><strong>机制</strong>：隐藏层的输出经过 sigmoid，被压缩在 (0, 1) 区间内。输出层是线性组合，因此</p><blockquote><p>ŷ ∈ [ β₀ − Σⱼ|βⱼ| , β₀ + Σⱼ|βⱼ| ]</p></blockquote><p><strong>这是一个与输入无关的常数界。</strong> 无论输入 yₜ₋ᵢ 涨到多高，输出都出不了这个范围。</p><p><strong>后果</strong>：</p><ol><li>若训练期数据在某区间内，模型基本只能在这个区间内预测；</li><li>遇到单边趋势（持续上涨或下跌）时，预测会<strong>系统性滞后</strong>；</li><li>多步预测时，预测值被反复代回输入，误差会沿同一方向累积。</li></ol><p>★ 此外，<code>nnetar</code> 内部会把数据归一化到 [0, 1] 区间再训练，这进一步强化了&quot;输出有界&quot;的性质。所以<strong>NNAR 天生不适合有强趋势的序列</strong>，除非先做差分或退势。</p><h2 id="_10-5-缩放与信息泄漏" tabindex="-1">10.5 缩放与信息泄漏 <a class="header-anchor" href="#_10-5-缩放与信息泄漏" aria-label="Permalink to &quot;10.5 缩放与信息泄漏&quot;">​</a></h2><p><code>nnetar</code> 内部对数据做 min-max 归一化：</p><blockquote><p>y&#39; = (y − min) / (max − min)</p></blockquote><p>★ <strong>这里有一个隐蔽的泄漏陷阱</strong>：如果对<strong>全样本</strong>计算 min 和 max，那么训练时就已经用到了测试期的极值信息。正确做法是<strong>每个预测原点只使用该原点之前的数据</strong>计算 min/max。</p><p>这个细节很容易被忽略，因为归一化通常被当作&quot;预处理&quot;而不是&quot;建模步骤&quot;。但在滚动预测中，每个原点的缩放参数都不同，必须逐点重算。</p><h2 id="_10-6-随机性与可复现" tabindex="-1">10.6 随机性与可复现 <a class="header-anchor" href="#_10-6-随机性与可复现" aria-label="Permalink to &quot;10.6 随机性与可复现&quot;">​</a></h2><p>神经网络有三处随机性来源：</p><ol><li><strong>权重初始化</strong>（最常见）；</li><li><strong>样本顺序</strong>（若用随机梯度下降）；</li><li><strong>正则化中的随机丢弃</strong>（若用 dropout）。</li></ol><p><strong>处理办法</strong>：</p><ul><li><strong>固定随机种子</strong>。R 中用 <code>set.seed()</code>。注意 <code>nnetar</code> 内部会多次调用随机数生成器，所以种子的效果依赖调用顺序。</li><li><strong>多次重复取平均</strong>（repeats）。这既降低方差，也让结果对单次初始化的偶然性不敏感。</li><li><strong>种子设计</strong>。若做滚动预测，可以让种子随原点变化（如&quot;固定常数 + 原点序号&quot;），既保证每个原点可复现，又避免所有原点用同一组初始权重而产生系统性偏差。</li></ul><p>★ <strong>报告里必须写明种子</strong>。否则同样的代码在不同机器上会得到不同结果，可复现性无从谈起。</p><h2 id="_10-7-为什么神经网络在月度经济序列上常输给-arima" tabindex="-1">10.7 为什么神经网络在月度经济序列上常输给 ARIMA <a class="header-anchor" href="#_10-7-为什么神经网络在月度经济序列上常输给-arima" aria-label="Permalink to &quot;10.7 为什么神经网络在月度经济序列上常输给 ARIMA&quot;">​</a></h2><p>四个原因：</p><ol><li><strong>样本量不足</strong>。月度数据几十年也只有几百个点，而神经网络的有效参数可能有几十个。参数/样本比过高。</li><li><strong>信噪比低</strong>。经济与金融序列的随机成分占比高，非线性结构微弱，神经网络容易拟合噪声。</li><li><strong>线性结构占主导</strong>。大量实证表明，多数经济时间序列的一阶、二阶矩结构已能被 ARIMA 捕捉，剩下的非线性部分不足以抵消额外的估计方差。</li><li><strong>缺乏外推能力</strong>（见 10.4）。有趋势的序列上，这一点是致命伤。</li></ol><p>★ 这不是&quot;神经网络不行&quot;，而是&quot;在这个数据条件下，简单模型的偏差–方差权衡更优&quot;。M4、M5 竞赛的结论是：<strong>组合模型（含统计模型与机器学习的加权组合）表现最好，单一神经网络很少夺冠</strong>。</p><h2 id="_10-8-什么时候-nnar-有优势" tabindex="-1">10.8 什么时候 NNAR 有优势 <a class="header-anchor" href="#_10-8-什么时候-nnar-有优势" aria-label="Permalink to &quot;10.8 什么时候 NNAR 有优势&quot;">​</a></h2><ul><li><strong>明显的非线性结构</strong>：阈值效应、饱和效应、状态依赖（如经济周期的扩张/收缩阶段）。</li><li><strong>大样本</strong>：高频数据（分钟级、日级）或长历史。</li><li><strong>多序列联合建模</strong>（global model）：把成百上千条相关序列一起训练，共享参数，等效于扩大样本。</li><li><strong>作为组合中的一员</strong>：即使单独表现不佳，若其误差与其他模型不相关，组合后仍能改善。</li></ul><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ol><li>NNAR(p,k) 是 AR(p) 的非线性推广，无隐藏层时退化为线性 AR。</li><li>关键超参数是 p（记忆长度）、k（隐藏节点数）、decay（权重衰减）、repeats（重复平均）。</li><li>隐藏层的 sigmoid 使输出有常数上界，因此 NNAR 不做趋势外推，遇单边趋势会系统性滞后。</li><li>归一化的 min/max 必须只用训练前缀计算，否则是信息泄漏。</li><li>必须设随机种子并报告；repeats 取平均既降方差又提高稳健性。</li><li>小样本、低信噪比、强趋势的场景下，NNAR 常输给 ARIMA，这是偏差–方差权衡的结果。</li></ol><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：NNAR(p,k) 和 AR(p) 是什么关系？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>NNAR(p,k) 是 <strong>AR(p) 的非线性推广</strong>：输入是前 p 个滞后值，隐藏层有 k 个节点。</p><p><strong>没有隐藏层时，它就退化成线性 AR</strong>。</p></details><p><strong>Q2：NNAR 为什么不能做趋势外推？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>隐藏层的 <strong>sigmoid 输出有上下界</strong>，所以网络输出也有常数上界。</p><p>遇到单边趋势时，预测会<strong>系统性滞后</strong>，跟不上趋势。</p></details><p><strong>Q3：为什么在小样本月度经济序列上，NNAR 常常输给 ARIMA？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>这是<strong>偏差–方差权衡</strong>的结果：小样本、低信噪比、强趋势的场景下，神经网络参数多、方差大，又不能外推趋势。</p><p>另外要注意两点：归一化的 min/max <strong>只能用训练段</strong>计算；要<strong>设随机种子</strong>并用 repeats 取平均，降方差、提高稳健性。</p></details>',52)])])}const m=o(n,[["render",l]]);export{u as __pageData,m as default};
